import fs from 'node:fs';

const adminPath = 'src/components/AdminDashboardView.tsx';
const admin = `import React, { useEffect, useMemo, useState } from 'react';
import { Activity, CreditCard, Database, ShieldCheck, Users, WalletCards } from 'lucide-react';
import { ViewType, DisplayCurrency } from '../types';
import AdminFundingQueue from './AdminFundingQueue';
import AdminPaymentMethods from './AdminPaymentMethods';
import { authHeaders } from '../utils/authHeaders';

interface AdminDashboardViewProps { transactions: any[]; updateTransactionStatus: (id: string, status: string) => void; setLiveBalance: React.Dispatch<React.SetStateAction<number>>; liveBalance: number; setView: (view: ViewType) => void; showToast: (msg: string, type: 'success' | 'error' | 'info') => void; displayCurrency?: DisplayCurrency; setDisplayCurrency?: (curr: DisplayCurrency) => void; formatCurrency?: (usdAmount: number, targetCurrency?: DisplayCurrency, decimals?: number) => string; }
type Tab = 'overview' | 'funding' | 'payments' | 'users' | 'activity';

export default function AdminDashboardView({ setView, showToast, transactions, displayCurrency = 'USD' }: AdminDashboardViewProps) {
  const [activeTab, setActiveTab] = useState<Tab>('overview');
  const [users, setUsers] = useState<any[]>([]);
  const [logs, setLogs] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const pendingCount = useMemo(() => transactions.filter((tx) => ['pending','awaiting'].some((s) => String(tx?.status ?? '').toLowerCase().includes(s))).length, [transactions]);
  useEffect(() => { document.title = 'Axi Trades Admin'; }, []);
  const loadUsers = async () => { setLoading(true); try { const res = await fetch('/api/users', { headers: await authHeaders() }); const data = await res.json(); if (!res.ok) throw new Error(data?.error || 'Unable to load users'); setUsers(Array.isArray(data.users) ? data.users : []); } catch (e: any) { showToast(e?.message || 'Unable to load users.', 'error'); } finally { setLoading(false); } };
  const loadActivity = async () => { setLoading(true); try { const res = await fetch('/api/admin/activity?limit=200', { headers: await authHeaders() }); const data = await res.json(); if (!res.ok) throw new Error(data?.error || 'Unable to load audit activity'); setLogs(Array.isArray(data.logs) ? data.logs : []); } catch (e: any) { showToast(e?.message || 'Unable to load activity.', 'error'); } finally { setLoading(false); } };
  useEffect(() => { if (activeTab === 'users') void loadUsers(); if (activeTab === 'activity') void loadActivity(); }, [activeTab]);
  const setUserStatus = async (userId: string, status: string) => { try { const res = await fetch('/api/users/' + encodeURIComponent(userId) + '/status', { method: 'PUT', headers: await authHeaders({ 'Content-Type': 'application/json' }), body: JSON.stringify({ status }) }); const data = await res.json(); if (!res.ok) throw new Error(data?.error || 'User status update failed'); setUsers((current) => current.map((u) => u.id === userId ? { ...u, status } : u)); showToast('User status changed to ' + status + '.', 'success'); } catch (e: any) { showToast(e?.message || 'User status update failed.', 'error'); } };
  const tabs = [{ id:'overview',label:'Overview',icon:<Activity className="h-4 w-4"/> },{id:'funding',label:'Funding',icon:<WalletCards className="h-4 w-4"/>},{id:'payments',label:'Payment Methods',icon:<CreditCard className="h-4 w-4"/>},{id:'users',label:'Users',icon:<Users className="h-4 w-4"/>},{id:'activity',label:'Audit Activity',icon:<ShieldCheck className="h-4 w-4"/>}];
  return <div className="min-h-screen bg-slate-950 text-white"><header className="border-b border-white/10 px-6 py-5"><div className="mx-auto flex max-w-7xl items-center justify-between gap-4"><div><p className="text-[10px] font-black uppercase tracking-[0.25em] text-red-400">Production Control Center</p><h1 className="mt-1 text-2xl font-bold">Axi Trades Admin</h1><p className="mt-1 text-sm text-slate-400">Live operational data only. No demo balances, seeded records or simulated activity.</p></div><button type="button" onClick={() => setView('dashboard' as ViewType)} className="rounded-lg border border-white/10 px-4 py-2 text-sm hover:bg-white/5">Back to Dashboard</button></div></header><main className="mx-auto max-w-7xl space-y-6 p-6"><section className="grid gap-4 sm:grid-cols-3"><div className="rounded-xl border border-white/10 bg-white/[0.03] p-5"><p className="text-xs uppercase tracking-wider text-slate-400">Pending transactions</p><p className="mt-2 text-2xl font-semibold">{pendingCount}</p></div><div className="rounded-xl border border-white/10 bg-white/[0.03] p-5"><p className="text-xs uppercase tracking-wider text-slate-400">Display currency</p><p className="mt-2 text-2xl font-semibold">{displayCurrency}</p></div><div className="rounded-xl border border-white/10 bg-white/[0.03] p-5"><p className="text-xs uppercase tracking-wider text-slate-400">Data authority</p><p className="mt-2 flex items-center gap-2 text-lg font-semibold"><Database className="h-5 w-5 text-emerald-400"/> PostgreSQL</p></div></section><nav className="flex flex-wrap gap-2 border-b border-white/10 pb-3">{tabs.map((tab)=><button key={tab.id} type="button" onClick={()=>setActiveTab(tab.id)} className={'inline-flex items-center gap-2 rounded-lg px-4 py-2 text-sm font-medium transition '+(activeTab===tab.id?'bg-white text-slate-950':'bg-white/5 text-slate-300 hover:bg-white/10')}>{tab.icon}{tab.label}</button>)}</nav>{activeTab==='overview'&&<section className="rounded-xl border border-white/10 bg-white/[0.03] p-6"><h2 className="text-lg font-semibold">Production operations</h2><p className="mt-1 text-sm text-slate-400">Operational modules below connect to protected production APIs.</p><div className="mt-5 grid gap-4 md:grid-cols-3"><button type="button" onClick={()=>setActiveTab('funding')} className="rounded-xl border border-white/10 bg-black/20 p-5 text-left hover:border-red-500/40"><WalletCards className="h-5 w-5 text-red-400"/><p className="mt-3 font-semibold">Funding queue</p><p className="mt-1 text-xs text-slate-400">Review real pending deposits.</p></button><button type="button" onClick={()=>setActiveTab('payments')} className="rounded-xl border border-white/10 bg-black/20 p-5 text-left hover:border-red-500/40"><CreditCard className="h-5 w-5 text-red-400"/><p className="mt-3 font-semibold">Payment configuration</p><p className="mt-1 text-xs text-slate-400">Manage production payment methods.</p></button><button type="button" onClick={()=>setActiveTab('activity')} className="rounded-xl border border-white/10 bg-black/20 p-5 text-left hover:border-red-500/40"><ShieldCheck className="h-5 w-5 text-red-400"/><p className="mt-3 font-semibold">Security audit</p><p className="mt-1 text-xs text-slate-400">Inspect server audit events.</p></button></div></section>}{activeTab==='funding'&&<AdminFundingQueue showToast={showToast}/>} {activeTab==='payments'&&<AdminPaymentMethods showToast={showToast}/>} {activeTab==='users'&&<section className="rounded-xl border border-white/10 bg-white/[0.03] p-6"><div className="flex items-center justify-between"><div><h2 className="text-lg font-semibold">User accounts</h2><p className="text-sm text-slate-400">Protected API data. No client-side user ledger.</p></div><button type="button" onClick={()=>void loadUsers()} className="rounded-lg border border-white/10 px-3 py-2 text-sm">Refresh</button></div>{loading?<p className="mt-6 text-sm text-slate-400">Loading production records…</p>:users.length===0?<p className="mt-6 rounded-lg border border-dashed border-white/10 p-6 text-center text-sm text-slate-500">No user records returned.</p>:<div className="mt-5 overflow-x-auto"><table className="w-full min-w-[720px] text-left text-sm"><thead className="border-b border-white/10 text-xs uppercase text-slate-500"><tr><th className="p-3">User</th><th className="p-3">Email</th><th className="p-3">Status</th><th className="p-3">Action</th></tr></thead><tbody>{users.map((user)=><tr key={String(user.id)} className="border-b border-white/5"><td className="p-3 font-medium">{String(user.name||user.displayName||user.id)}</td><td className="p-3 text-slate-400">{String(user.email||'—')}</td><td className="p-3">{String(user.status||'active')}</td><td className="p-3"><select value={String(user.status||'active')} onChange={(e)=>void setUserStatus(String(user.id),e.target.value)} className="rounded-md border border-white/10 bg-slate-900 px-2 py-1 text-xs"><option value="active">Active</option><option value="suspended">Suspended</option><option value="pending">Pending</option></select></td></tr>)}</tbody></table></div>}</section>} {activeTab==='activity'&&<section className="rounded-xl border border-white/10 bg-white/[0.03] p-6"><div className="flex items-center justify-between"><div><h2 className="text-lg font-semibold">Administrative audit trail</h2><p className="text-sm text-slate-400">Server-side events only.</p></div><button type="button" onClick={()=>void loadActivity()} className="rounded-lg border border-white/10 px-3 py-2 text-sm">Refresh</button></div>{loading?<p className="mt-6 text-sm text-slate-400">Loading audit records…</p>:logs.length===0?<p className="mt-6 rounded-lg border border-dashed border-white/10 p-6 text-center text-sm text-slate-500">No audit records available.</p>:<div className="mt-5 space-y-2">{logs.map((log,index)=><div key={String(log.id||index)} className="rounded-lg border border-white/10 bg-black/20 p-4"><div className="flex justify-between gap-2"><strong>{String(log.action||log.event||'AUDIT_EVENT')}</strong><span className="text-xs text-slate-500">{String(log.created_at||log.createdAt||'')}</span></div><p className="mt-1 text-xs text-slate-400">Actor: {String(log.actor||log.email||'system')}</p></div>)}</div>}</section>}</main></div>;
}
`;
fs.writeFileSync(adminPath, admin);

const promoPath = 'src/components/PromotionsView.tsx';
if (fs.existsSync(promoPath)) {
  let promo = fs.readFileSync(promoPath, 'utf8');
  const replacements = [
    ['50% Welcome Trading Credit', '100% Deposit Bonus'],
    ['50% Welcome Tradable Credit', '100% Deposit Bonus'],
    ['50% Deposit Booster', '100% Deposit Bonus'],
    ['Claim 50% Welcome Bonus', 'Claim 100% Deposit Bonus'],
    ['50% tradable margin credit', '100% promotional credit'],
    ['+50%', '+100%']
  ];
  for (const [from, to] of replacements) promo = promo.split(from).join(to);
  fs.writeFileSync(promoPath, promo);
}

console.log('Production UI hardening applied.');
